def icon(name): return f'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{icons[name]}</svg>'
def button(name,label,cls=''):return f'<button class="icon-button {cls}" aria-label="{label}">{icon(name)}</button>'
def avatar(name,cls=''):return f'<span class="avatar {cls}" aria-hidden="true">{name}</span>'
def status():return '<div class="status"><b>9:41</b><span class="island"></span><span class="signal">▮▮▮ <b>◒</b> ▰</span></div>'
def tabs(selected=0):
 return '<nav class="tabs" aria-label="Điều hướng chính">'+''.join(f'<button class="tab {"selected" if i==selected else ""}">{icon(n)}<span>{t}</span></button>' for i,(n,t) in enumerate([('map','Bản đồ'),('chat','Tin nhắn'),('clock','Ở đây'),('route','Lộ trình'),('more','Thêm')]))+'<div class="home"></div></nav>'
def map_drawing():
 return '''<svg class="map-drawing" viewBox="0 0 390 844" preserveAspectRatio="none" aria-hidden="true">
 <rect width="390" height="844" class="land"/>
 <path d="M320-20C250 140 380 230 300 390S300 630 400 850" class="river"/>
 <g class="park"><rect x="24" y="206" width="94" height="72" rx="14"/><rect x="196" y="420" width="75" height="100" rx="16"/><rect x="25" y="542" width="78" height="94" rx="16"/></g>
 <g class="blocks"><rect x="132" y="203" width="70" height="68" rx="8"/><rect x="32" y="300" width="74" height="62" rx="8"/><rect x="130" y="300" width="71" height="65" rx="8"/><rect x="214" y="307" width="58" height="66" rx="8"/><rect x="38" y="394" width="66" height="83" rx="8"/><rect x="126" y="401" width="49" height="84" rx="8"/><rect x="122" y="533" width="57" height="71" rx="8"/><rect x="194" y="544" width="70" height="63" rx="8"/></g>
 <g class="roads"><path d="M-30 290 400 275M-20 385 390 386M-20 518 400 518M117 170v550M212 180v235M185 390v330M20 655l340-40"/></g>
 <g class="street-label"><text x="140" y="286">ĐƯỜNG A</text><text x="29" y="383">ĐƯỜNG B</text><text x="36" y="242">Công viên</text><text x="216" y="468">Vườn nhỏ</text><text transform="translate(323 345) rotate(73)">Sông minh hoạ</text></g>
 </svg>'''
def markers():
 return f'<div class="marker p1">{avatar("L", "purple")}<span>Linh</span></div><div class="marker p2">{avatar("M", "blue")}<span>Minh</span></div><div class="self-dot" aria-label="Vị trí của bạn, dữ liệu giả lập"></div>'
def top():
 return f'<header class="map-header"><div class="brand">FamilyTracker</div><button class="people-button">{icon("people")}<span>3</span><span class="sr-only">thành viên</span></button><button class="search-entry">{icon("search")}<span>Tìm địa điểm</span></button></header>'
def compact_members():
 return f'<section class="member-strip"><div class="section-line"><b>Thành viên</b><button class="text-button">Xem tất cả</button></div><div class="avatar-list">{avatar("L","purple")}<div><b>Linh</b><small>Cập nhật 14:30</small></div>{avatar("M","blue")}<div><b>Minh</b><small>Cập nhật 14:26</small></div></div></section>'
def detail():
 return f'''<section class="detail-sheet"><div class="grabber"></div><div class="detail-top">{avatar("L","purple")}<div><h2>Linh</h2><p>Cập nhật lúc 14:30</p></div>{button('close','Đóng thông tin')}</div><div class="detail-meta"><span>{icon('pin')}Vị trí trên bản đồ</span><span>Pin 72%</span></div><p class="muted helper">Đây là vị trí ghi nhận gần nhất.</p><div class="two-actions"><button class="primary">{icon('location')}Xem vị trí</button><button class="secondary">{icon('route')}Lộ trình</button></div></section>'''
def map_screen(mode,kind='map'):
 controls=f'<div class="map-controls">{button("location","Về vị trí của tôi")}<button class="icon-button sos" aria-label="Yêu cầu SOS">SOS</button></div>'
 notice='<div class="network-warning">'+icon('wifi')+'<div><b>Mất kết nối realtime</b><small>Vị trí có thể chưa được cập nhật.</small></div></div>' if kind=='offline' else ''
 sheet=detail() if kind=='member' else compact_members()
 return f'<div class="phone {mode} map-screen {kind}-state">{map_drawing()}{status()}{top()}{notice}{markers()}{controls}<small class="map-credit">Vùng attribution MapKit</small>{sheet}{tabs()}</div>'
def row(title,subtitle='',ico=None,trailing=None):
 return f'<div class="settings-row">{icon(ico) if ico else ""}<div><b>{title}</b>{f"<small>{subtitle}</small>" if subtitle else ""}</div><span class="row-trailing">{trailing or icon("chevron")}</span></div>'
def profile(mode):
 return f'''<div class="phone {mode} settings-screen">{status()}<header class="page-title"><h1>Cá nhân</h1></header><main><section class="settings-group identity">{avatar('A','purple')}<div><h2>An Nguyễn</h2><p>an@example.test</p></div></section><h3>Cài đặt</h3><section class="settings-group">{row('Ngôn ngữ','Tiếng Việt')}{row('Giao diện','Theo hệ thống','moon')}</section><h3>Quyền riêng tư</h3><section class="settings-group">{row('Chia sẻ vị trí','Đang chia sẻ · dữ liệu giả lập','shield','<span class="toggle"></span>')}</section><p class="group-note">Bạn có thể thay đổi trạng thái chia sẻ tại đây.</p><h3>Nhà phát triển <span class="debug-badge">CHỈ DEBUG</span></h3><section class="settings-group">{row('Chẩn đoán mạng','Mở Pulse · log và xuất JSON','pulse')}</section><p class="group-note">Bản Release không hiển thị mục này.</p><button class="logout">Đăng xuất</button></main>{tabs(4)}</div>'''
def appearance(mode):
 rows=''.join(f'<button class="appearance-row" data-theme-choice="{key}"><span class="preview-icon">{icon(ico)}</span><div><b>{name}</b><small>{sub}</small></div><span class="radio {"checked" if key=="system" else ""}">{icon("check") if key=="system" else ""}</span></button>' for key,name,sub,ico in [('system','Theo hệ thống','Tự đổi theo cài đặt iPhone','system'),('light','Sáng','Luôn dùng giao diện sáng','sun'),('dark','Tối','Luôn dùng giao diện tối','moon')])
 return f'<div class="phone {mode} settings-screen">{status()}<header class="navigation">{button("back","Quay lại Cá nhân")}<b>Giao diện</b><span></span></header><main><p class="appearance-lead">Chọn cách FamilyTracker hiển thị trên thiết bị này.</p><section class="settings-group">{rows}</section><p class="group-note">Lựa chọn được lưu trên thiết bị và áp dụng cho bản đồ, màn hình và sheet.</p><div class="theme-sample">{icon("map")}<div><b>Bản đồ rõ ràng, cả ngày lẫn đêm.</b><p>Cùng bố cục. Cùng thông tin. Màu sắc thích ứng.</p></div></div></main><div class="home"></div></div>'
def search(mode):
 return f'''<div class="phone {mode} map-screen search-screen">{map_drawing()}{status()}<div class="map-context">{avatar('M','blue')}<span>Minh</span></div><section class="search-sheet"><div class="grabber"></div><div class="search-bar"><div>{icon('search')}<span>Công viên</span>{button('close','Xoá nội dung tìm kiếm')}</div><button class="text-button">Huỷ</button></div><div class="search-context">Tìm trong vùng bản đồ đang xem</div><div class="search-state"><div class="section-line"><h3>Kết quả</h3><span>Minh hoạ</span></div>{row('Công viên An Bình','Khu A · địa điểm giả lập','pin')}{row('Vườn ven sông','Khu B · địa điểm giả lập','pin')}<p class="group-note">Chọn một kết quả để ghim lên bản đồ.</p></div></section><div class="keyboard" aria-label="Bàn phím minh hoạ"><div>q w e r t y u i o p</div><div>a s d f g h j k l</div><div>⇧ z x c v b n m ⌫</div><div><span>123</span><span class="space">dấu cách</span><span class="key-search">Tìm</span></div></div><div class="home"></div></div>'''
