items=[]
for kind,code,title,note in [
 ('map','M01','Bản đồ · mặc định','Search luôn ở vùng trên. Recenter và SOS giữ ngoài panel. Không có nút Pulse nổi; tab Thêm minh hoạ overflow của sáu destination hiện có.'),
 ('member','M02','Chi tiết thành viên','Tách thời điểm cập nhật khỏi online. Xem vị trí chỉ căn lại bản đồ; Lộ trình giữ route hiện có. Không thêm chỉ đường từng chặng.'),
 ('search','M03','Tìm địa điểm','Giữ entry trên cùng; sheet kết quả có Huỷ và phần bản đồ còn nhìn thấy. Bàn phím/vị trí attribution chỉ minh hoạ, cần native QA.'),
 ('profile','M04','Cá nhân · cài đặt','Thêm Giao diện vào cài đặt; dùng lại mục Nhà phát triển cho Pulse. Lựa chọn chia sẻ chỉ là fixture, không thay consent.'),
 ('appearance','M05','Lựa chọn giao diện','Theo hệ thống là mặc định. Ba lựa chọn lưu trên thiết bị; proposal chưa tích hợp vào app. Tương tác ở đây chỉ là bản thử HTML.'),
 ('offline','M06','Bản đồ · mất realtime','Thông báo kết nối ở đúng ngữ cảnh. Giữ timestamp cuối; không biến mất mạng của máy này thành trạng thái offline của mọi thành viên.')]:
 for mode in ['light','dark']:
  key=f'{kind}-{mode}'
  phone=map_screen(mode,kind) if kind in ['map','member','offline'] else {'search':search,'profile':profile,'appearance':appearance}[kind](mode)
  items.append(dict(key=key,code=code,title=title,mode=mode,note=note))
  items[-1]['html']=f'<article class="design-card" id="{key}"><div class="caption"><b>{code} · {title}</b><span>{mode.upper()} · V1 / PROPOSED</span></div>{phone}<p class="design-note">{note}</p></article>'
header='''<header class="review-header"><div class="review-status">FAMILYTRACKER / DESIGN REVIEW / V1 · PROPOSED</div><h1>Bản đồ trước. Thông tin rõ ràng.</h1><p>Đề xuất thiết kế để duyệt, chưa phải giao diện đã triển khai. Tất cả người, vị trí và số liệu là giả lập; bản đồ là sơ đồ tự vẽ, không phải ảnh MapKit. Giữ màu indigo và SF Rounded hiện có, ưu tiên map, timestamp thật và control native.</p><nav class="review-nav">'''+''.join(f'<a href="#{k}-light">{t}</a>' for k,t in [('map','01 Bản đồ'),('member','02 Thành viên'),('search','03 Tìm kiếm'),('profile','04 Cá nhân'),('appearance','05 Giao diện'),('offline','06 Mất kết nối')])+'''<a href="../ui-ux-audit.md">Báo cáo audit</a></nav></header>'''
script='''const key=new URLSearchParams(location.search).get('render');if(key){document.body.classList.add('render');document.getElementById(key)?.classList.add('active')}document.querySelectorAll('[data-theme-choice]').forEach(button=>button.addEventListener('click',()=>{const phone=button.closest('.phone');phone.querySelectorAll('.radio').forEach(r=>{r.classList.remove('checked');r.innerHTML=''});const r=button.querySelector('.radio');r.classList.add('checked');r.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m4 12 5 5L20 6"/></svg>';const mode=button.dataset.themeChoice;phone.classList.toggle('dark',mode==='dark'||(mode==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches))}));'''
footer='''<footer class="review-footer"><b>Quyết định cần duyệt theo mã và phiên bản.</b><br>M01+M02: bố cục map/member; M03: search sheet; M04+M05: theme và Pulse; M06: thông báo mất realtime. Có thể duyệt, yêu cầu sửa hoặc từ chối từng mục. Chưa có mục nào được APPROVED. Các nút khác là hình thức minh hoạ, không gọi API hoặc giả lập chức năng đã triển khai.</footer>'''
html='<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FamilyTracker — duyệt thiết kế V1</title><style>'+css+'</style><body>'+header+'<div class="gallery">'+''.join(x['html'] for x in items)+'</div>'+footer+'<script>'+script+'</script></body></html>'
(OUT/'index.html').write_text(html)
(OUT/'manifest.json').write_text(json.dumps([{k:v for k,v in x.items() if k!='html'} for x in items],ensure_ascii=False,indent=2))
print('Generated',len(items),'mockup panels in',OUT/'index.html')
